import{_ as t,o as n,c as e,a2 as s,j as i,a}from"./chunks/framework.DxqK4cCD.js";const m=JSON.parse('{"title":"PrimeSVT: An Automated Memory-aware Pruning Framework with Prioritized Compression Policy for Spiking Vision Transformers","description":"PrimeSVT提出一种自动化、内存感知的结构化剪枝框架，通过优先级压缩策略高效压缩脉冲视觉Transformer，实现硬件友好的模型部署。","frontmatter":{"title":"PrimeSVT: An Automated Memory-aware Pruning Framework with Prioritized Compression Policy for Spiking Vision Transformers","description":"PrimeSVT提出一种自动化、内存感知的结构化剪枝框架，通过优先级压缩策略高效压缩脉冲视觉Transformer，实现硬件友好的模型部署。","date":"2026-06-06","arxivId":"2606.03428","domain":"类脑计算 · 人工智能 · 机器学习","level":"进阶","tags":["脉冲视觉Transformer","结构化剪枝","模型压缩","自动化机器学习","内存优化"],"originalUrl":"https://arxiv.org/abs/2606.03428","sourceUrl":"https://github.com/vsvnakers/paper-daily/blob/master/essay_read/2026-06-06/2606.03428.md"},"headers":[],"relativePath":"papers/daily/2026-06-06/2606.03428.md","filePath":"papers/daily/2026-06-06/2606.03428.md","lastUpdated":1786541753000}'),l={name:"papers/daily/2026-06-06/2606.03428.md"};function o(h,r,p,d,g,k){return n(),e("div",null,[...r[0]||(r[0]=[s("",15),i("ul",null,[i("li",null,[i("strong",null,"优先级压缩策略（Prioritized Compression Policy）"),a("：PrimeSVT的核心调度算法。它首先计算SViT模型中每一层的参数数量（即层大小），并按降序排列。然后，它通过一个鲁棒性评估步骤，对每一层进行不同剪枝率（如10%, 20%, ...）的快速剪枝测试，观察精度下降情况，从而确定该层对剪枝的敏感度。最终，它生成一个压缩顺序列表，优先处理“大且鲁棒”的层。")]),i("li",null,[i("strong",null,"内存感知约束（Memory-aware Constraints）"),a("：用户需要提供两个关键约束：目标内存节省率（如30%）和可接受的精度损失（如3%）。PrimeSVT的压缩过程会持续进行，直到达到内存节省目标或精度下降超出阈值。这确保了压缩结果满足用户的实际部署需求。")]),i("li",null,[i("strong",null,"基于L2范数的通道级剪枝（Channel-wise L2-norm based Filter Pruning）"),a("：在选定要剪枝的层后，PrimeSVT计算该层中每个卷积滤波器（或全连接层的神经元）的L2范数。L2范数定义为权重向量各元素平方和的平方根，即 $||W_i||"),i("em",{j:""},"2 = \\sqrt{\\sum"),a(" w_{ij}^2}$，其中 $W_i$ 是第 $i$ 个滤波器的权重向量。具有较小L2范数的滤波器被认为重要性较低，因此被移除。")]),i("li",null,[i("strong",null,"单次剪枝（Single-shot Pruning）"),a("：与需要迭代训练-剪枝-微调的方法不同，PrimeSVT在预训练模型上执行一次性的剪枝操作。剪枝后，模型可以直接使用（无需微调）或进行少量微调（Fine-tuning）以恢复精度。这大大简化了压缩流程。")]),i("li",null,[i("strong",null,"结构化剪枝的兼容性"),a("：通过移除整个滤波器，PrimeSVT直接减少了模型中的权重矩阵维度。例如，一个形状为 $[C_{out}, C_{in}, K, K]$ 的卷积层，如果剪掉 $m$ 个滤波器，其输出通道数变为 $C_{out} - m$，对应的后续层输入通道数也相应减少。这种结构变化是规则且连续的，无需特殊硬件支持。")])],-1),s("",5),i("p",null,[a("【核心公式】 PrimeSVT的核心操作是基于L2范数的滤波器重要性评估。对于一个卷积层，其第 $i$ 个滤波器的L2范数定义为： $$\\text{Importance}(F_i) = ||W_i||"),i("em",{j:"1"},"2 = \\sqrt{\\sum"),a("^{N} w_{ij}^2}$$ 其中 $W_i$ 是第 $i$ 个滤波器的权重向量，包含 $N$ 个权重值 $w_{ij}$。该值越小，表示滤波器越不重要，越有可能被剪掉。")],-1),s("",37)])])}const c=t(l,[["render",o]]);export{m as __pageData,c as default};
